const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_1","ls":"6.1","title":"Lernpfadübung · LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_1_Standorte_vergleichen.md"};
const COMP=[["Fachkompetenz","Ich vergleiche zwei Läden. Ich schaue auf Nachfrage, Verkaufsform und Fläche. Aus den Unterschieden leite ich Anforderungen an das Sortiment und die Warenpräsentation ab. Ich begründe diese Anforderungen für jeden Laden. Ich erkenne, welche Vorgaben der Laden unbedingt erfüllen muss."],["Personalkompetenz","Ich prüfe meine erste Idee mit Belegen."],["Sozialkompetenz","Ich höre die Ideen der anderen an. Ich begründe im Team, was für mich am wichtigsten ist."],["Methodenkompetenz","Ich ordne die Angaben zu beiden Läden nach denselben Kriterien."],["Medienkompetenz","Ich finde in einer Tabelle, Sprachnachricht oder Skizze die Angaben für meine Entscheidung."]];
const BANK=[{"c":0,"title":"Nachfrage bei Block","scene":"Block in Aurich erfasst 20 Kundenanfragen. Neun betreffen Sichtbarkeit auf dem Arbeitsweg, sechs das sichere Abstellen und fünf den Transport kleiner Dinge.","ask":"Welche Aussagen kannst du aus den Zahlen ableiten?","answer":[1,4],"options":["Das sichere Abstellen wurde am häufigsten genannt.","Sichtbarkeit auf dem Arbeitsweg ist das häufigste Hauptanliegen.","Bei 20 Anfragen wurden 20 Artikel verkauft.","Die Nachfrage nach Transport überwiegt die Nachfrage nach Sichtbarkeit.","Auch das sichere Abstellen ist ein belegter Kundenwunsch.","Genau neun Kundinnen und Kunden haben ein Lichtset gekauft."],"why":"Neun ist der höchste Wert. Auch die sechs Anfragen zum sicheren Abstellen belegen einen Bedarf. Die Angaben zählen Anfragen, keine Käufe.","hint":"Achte darauf, was gezählt wurde.","steps":"Vergleiche erst die drei Zahlen. Prüfe dann, ob die Antwort über Anfragen oder über Verkäufe spricht.","example":"Wenn acht Personen nach einem Produkt fragen, kann der Laden daraus noch keine acht Verkäufe ableiten.","sourceRefs":["M1"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Nachfrage in der Bike Arena","scene":"Die Bike Arena Oltmanns in Leer erfasst 20 Anfragen. Acht betreffen Familienausflüge, sieben Reparaturen unterwegs, fünf besseren Regenschutz.","ask":"Welche Aussagen passen zum Profil der Kundschaft?","answer":[0,3,5],"options":["Familienausflüge wurden häufiger genannt als besserer Regenschutz.","Regenschutz wurde für die Aktion gar nicht nachgefragt.","Reparaturen unterwegs sind das Hauptanliegen von genau der Hälfte der Anfragen.","Die sieben Anfragen zu Reparaturen liefern einen weiteren Ansatz für die Auswahl.","Die meisten Anfragen betreffen ausschließlich Regenschutz.","Auch Regenschutz kam vor, selbst wenn er seltener genannt wurde."],"why":"Familienausflüge liegen mit acht vor Reparaturen mit sieben und Regenschutz mit fünf. Alle drei Themen wurden angesprochen.","hint":"Ordne die drei Anliegen nach der Zahl ihrer Nennungen.","steps":"Beurteile jede Aussage einzeln. Fünf von 20 sind ein Viertel, zehn wären die Hälfte.","example":"Eine seltenere Anfrage kann für einen Teil der Zielgruppe wichtig sein.","sourceRefs":["M2"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Verkaufsformen vergleichen","scene":"Bei Block berät eine Fachkraft persönlich. In der Bike Arena wählt die Kundschaft auf der Aktionsfläche selbst; die Information ist bei Fragen ansprechbar.","ask":"Welche Merkmale der Verkaufsformen stimmen?","answer":[0,3],"options":["Bei Block ist eine Beratung am mitgebrachten Fahrrad möglich.","Selbstbedienung bedeutet, dass Fragen grundsätzlich unerwünscht sind.","In beiden Läden führt eine Fachkraft jede Person durch die Auswahl.","Auf der Aktionsfläche in Leer sollen Kundinnen und Kunden Waren selbst finden.","Der Satz ‚Die Aktion findet am Samstag statt‘ beschreibt die Verkaufsform.","Persönliche Beratung bedeutet, dass kein Schild verwendet werden darf."],"why":"Block kann Zubehör direkt am Fahrrad zeigen. In Leer soll die Auswahl zunächst selbstständig gelingen; für Rückfragen gibt es die Information.","hint":"Wer hilft bei der Auswahl? Wer sucht selbst aus?","steps":"Trenne Verkaufsform von Zeitpunkt, Fläche und Beschriftung.","example":"Trotz Selbstbedienung kann es eine Information geben, ohne dass jemand dauerhaft am Regal steht.","sourceRefs":["M1","M2"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Anfragen richtig einordnen","scene":"Im Ladenprofil wurde für jede Anfrage genau ein Hauptanliegen notiert. Eine Person fragt nach einem Schloss, weil sie ihr Rad am Bahnhof anschließen will.","ask":"Welche Einträge passen zu dieser Auswertung?","answer":[2,5],"options":["Diese Anfragedaten beweisen, wie oft Fahrräder am Bahnhof gestohlen werden.","Die Frage wird unabhängig vom Zweck beim Thema ‚Verkaufsfläche‘ erfasst.","Der konkrete Wunsch kann ein Nachfragebeleg sein.","Die Anfrage zählt zugleich in jeder denkbaren Zubehörgruppe.","Der sichere Abstellplatz ist hier das gemessene Hauptanliegen des ganzen Ladens.","Als Hauptanliegen passt ‚Fahrrad sicher abstellen‘."],"why":"Die Kundenfrage belegt einen Bedarf. Für die Auswertung erhält sie im Fall genau ein Hauptanliegen: das sichere Abstellen.","hint":"Achte auf den Zweck des Schlosses in dieser Anfrage.","steps":"Unterscheide eine einzelne Anfrage von der häufigsten Kategorie im gesamten Laden.","example":"Wenn jemand eine Tasche für den Schlüssel sucht, ordnest du die Anfrage dem Transport kleiner Dinge zu.","sourceRefs":["M1","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Platz und Warenträger","scene":"Block hat 3,60 m × 3,20 m Aktionsfläche mit festem Tresen. Für Leer sind 6,40 m × 3,50 m und zwei Gondeln vorgesehen.","ask":"Welche Aussagen helfen dir, den Aufbau richtig zu planen?","answer":[0,1,2,5],"options":["Bei der Planung für Block muss der Tresen an seiner festen Position berücksichtigt werden.","Gondeln sind freistehende Regale, die hier von beiden Seiten erreichbar sein sollen.","Der Tresen beansprucht einen Teil der Aktionsfläche bei Block.","Die beiden Gondeln gehören zur geplanten Ausstattung von Block.","Die genannten Aktionsmaße stehen für die gesamte Ladenfläche.","Die beiden Aktionsflächen bieten unterschiedlich viel Platz."],"why":"Block hat weniger Fläche und einen festen Tresen. Die Gondeln in Leer sind für Ware auf zwei gegenüberliegenden Seiten vorgesehen.","hint":"Ordne jedes Maß und jeden Warenträger seinem Standort zu.","steps":"Frage dich: Ist der Warenträger fest, rollbar oder von mehreren Seiten nutzbar?","example":"Ein Wandregal kann von vorn erreichbar sein; eine beidseitig belegte Gondel braucht Zugang auf beiden Warenseiten.","sourceRefs":["M3","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Skizze lesen","scene":"Für eure Skizzen gilt der Maßstab 1:25. Der Hauptdurchgang bei Block ist in Wirklichkeit 1,20 m breit.","ask":"Welche Angaben sind richtig?","answer":[0,4],"options":["Ein Zentimeter im Plan entspricht 25 Zentimetern im Laden.","Der Hauptdurchgang muss im Plan 3,0 cm breit sein.","Der Durchgang wird im Plan 48 cm breit.","Der Maßstab bedeutet, dass je Laden 25 Artikel eingeplant werden.","Der Hauptdurchgang ist in der Skizze 4,8 cm breit.","Im Maßstab 1:25 darf jeder Laden die Wege nach Gefühl einzeichnen."],"why":"1,20 m sind 120 cm. 120 ÷ 25 = 4,8 cm im Plan. Der Maßstab verkleinert Längen im selben Verhältnis.","hint":"Rechne zuerst in Zentimeter um.","steps":"Teile die tatsächliche Breite durch 25 und gib das Ergebnis in Zentimetern an.","example":"50 cm im Laden werden bei 1:25 zu 2 cm im Plan.","sourceRefs":["M3"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Die eigene Priorität prüfen","scene":"Du willst für Block ein zusätzliches Schild im Bereich des Werkstattzugangs aufstellen. Dann liest du, dass der Zugang frei bleiben muss. Die Ware kann auch am Regal klar beschriftet werden.","ask":"Welche Reaktion prüft deine erste Idee mit den Angaben zur Fläche?","answer":[3],"options":["Ich bleibe beim Schild am Zugang, weil ich es zuerst gewählt habe.","Ich nenne den Werkstattzugang und das Schild gleich wichtig und lasse die Entscheidung offen.","Ich frage, welche Schildfarbe meinem Team am besten gefällt.","Ich halte den Zugang frei und prüfe eine Regalbeschriftung als Alternative.","Ich mache die Freigabe davon abhängig, dass ein zusätzliches Schild eingesetzt wird.","Ich verschiebe die Beratungsfläche in den Hauptgang, damit das Schild seinen Platz behalten kann."],"why":"Der freie Zugang ist vorgegeben. Die Regalbeschriftung erreicht den Zweck des Schilds, wenn sie verständlich ist. So wird die erste Idee am Fall geprüft und bei Bedarf verändert.","hint":"Was darf dabei auf keinen Fall verloren gehen?","steps":"Vergleiche den Nutzen deiner Idee mit der festen Flächenvorgabe. Prüfe, ob eine andere Lösung denselben Nutzen hat.","example":"Wenn ein Möbel den Hauptgang versperrt, kannst du eine andere Position oder einen anderen Warenträger wählen.","sourceRefs":["M3","M5","M6"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Die erste Idee prüfen","scene":"Sarah schlägt ein gemeinsames Angebot und denselben Aufbau vor. Sebastian zeigt die unterschiedlichen Ladenprofile.","ask":"Welche Gedanken helfen, die erste Idee fair zu prüfen?","answer":[1,3,5],"options":["Die Vorbereitung wird einfacher, also muss derselbe Aufbau überall passen.","Ein gemeinsamer Rahmen für die Aktion und unterschiedliche Aufbauten können zusammenpassen.","Der Vorschlag von Sarah ist durch die unterschiedliche Fläche automatisch in jedem Teil widerlegt.","Ich prüfe die Idee getrennt an Kundenanfragen, Verkaufsform und Platz.","Wenn ich den Vorschlag mag, lasse ich störende Angaben aus der Matrix weg.","Ich halte fest, bei welchem konkreten Beleg ich meine erste Einschätzung ändere."],"why":"Sarahs Idee erleichtert die Vorbereitung. Erst der Vergleich zeigt, welche Teile man gemeinsam planen kann und wo Unterschiede eine eigene Lösung erfordern.","hint":"Unterscheide die Idee einer gemeinsamen Aktion vom identischen Aufbau.","steps":"Nenne den Vorteil der Idee. Prüfe danach pro Laden, wo sie an Grenzen stößt.","example":"Ein gemeinsames Motiv kann erhalten bleiben, wenn ein kleines Geschäft weniger Stellfläche hat.","sourceRefs":["Handlungssituation","M5"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Rückfragen im Team","scene":"Ein Teammitglied möchte für Leer einen gleichen Vorführtisch wie bei Block. Eine andere Person verweist auf die Selbstbedienung in Leer.","ask":"Welche Gesprächsbeiträge bringen euch weiter?","answer":[0,2,4],"options":["Ich frage nach, welchen Vorteil der Tisch in Leer bringen soll.","Ich entscheide allein, weil die Ideen zu verschieden sind.","Ich lege die Angaben zur Verkaufsform nebeneinander.","Ich stimme ab, bevor wir den Standortbeleg anschauen.","Ich erkläre meinen Vorschlag mit der konkreten Ladenbedingung.","Ich streiche den Einwand ohne Rückfrage, weil Block schon einen Tisch hat."],"why":"Mit einer Rückfrage, einem gemeinsamen Blick auf die Daten und einer begründeten eigenen Position klärt ihr, ob der Tisch für Leer sinnvoll wäre.","hint":"Hört euch erst an, welchen Bedarf jede Idee erfüllen soll.","steps":"Vergleicht danach die Begründungen mit der unterschiedlichen Verkaufsform.","example":"Ihr könnt eine Idee weiterentwickeln, indem ihr aus einer persönlichen Vorführung eine leicht verständliche Regalinfo macht.","sourceRefs":["M2","M3","M4"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Für Jan vorbereiten","scene":"Um 10 Uhr kommen beide Läden zur Besprechung. Jan Richter will wissen, welcher Unterschied für die Aktion am wichtigsten ist.","ask":"Welche Beiträge helfen dem Team, zu einer begründeten Einschätzung zu kommen?","answer":[2,4],"options":["Wir reichen zwei ungeprüfte Einzelmeinungen ohne Belege ein.","Wir beschreiben nur den Laden, den wir besser kennen.","Wir vergleichen dieselben Kriterien für beide Läden.","Wir einigen uns allein nach der optisch schönsten Skizze.","Wir erklären, wie sich unser wichtigster Unterschied auf den Aufbau auswirkt.","Wir legen die Anzahl der Regale zugrunde und blenden Beratung und Nachfrage aus."],"why":"Ein Vergleich nach denselben Kriterien zeigt Unterschiede. Für Jan muss daraus erkennbar sein, was diese Unterschiede für die Aktion bedeuten.","hint":"Denke von Jans Entscheidung aus: Was muss er nach eurem Beitrag wissen?","steps":"Nennt euren wichtigsten Unterschied und begründet, welche Folgen er für beide Standorte hat.","example":"Ein unterschiedlicher Bedarf an Beratung kann erklären, warum ein Laden Vorführplatz braucht und der andere klare Regalhinweise.","sourceRefs":["Handlungssituation","M5"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Quelle für den Beleg finden","scene":"Euch liegen Kurzprofile, eine Maßskizze und zwei Sprechtexte zu den Läden vor.","ask":"Welche Quellenwahl passt zur gesuchten Information?","answer":[1,3,4],"options":["Die korrekte Gangbreite übernehme ich aus der Zahl der Anfragen in M1.","Den Bedarf nach Sichtbarkeit bei Block belege ich mit dem Kurzprofil M1.","Die gesamte Ladenfläche verrät, welche Pumpe zu einem Ventil passt.","Für den Stellplatz des Tresens schaue ich in die Skizzenhilfe M3.","Für eine Kundenfrage zur Ventilpassung nutze ich das Kurzprofil M2 oder die Sprachnachricht M4.","Für den Werkstattzugang ist eine allgemeine Definition von Zielgruppe ausreichend."],"why":"Die Kurzprofile und Sprechtexte liefern konkrete Nachfragen. Die Skizzenhilfe enthält Maße und Positionen. Gesucht ist jeweils die Quelle, die genau zur Behauptung passt.","hint":"Kläre zuerst: Suchst du eine Äußerung, eine Zahl oder einen Ort im Plan?","steps":"Vergleiche den Inhalt der Quelle mit der Frage. Eine ähnliche Fragestellung reicht als Beleg nicht aus.","example":"Ein Lageplan zeigt dir, wo ein Tisch steht; ein Nachfrageprotokoll zeigt dir, warum jemand ein Licht sucht.","sourceRefs":["M1","M2","M3","M4"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Kundenstimmen auswerten","scene":"Eine Kundin fragt in Leer, welche Pumpe zu den Ventilen ihrer Familie passt. Ein Kunde bei Block möchte sehen, ob ein Schloss durch seinen Rahmen passt.","ask":"Welche Notizen geben die Stimmen verständlich und angemessen wieder?","answer":[0,2],"options":["Leer: Die Kundin braucht eine leicht auffindbare Angabe zur Ventilart.","Leer: Unsere Pumpen passen garantiert zu allen Ventilen.","Block: Der Kunde will die Passung des Schlosses am eigenen Rad prüfen.","Block: Der Kunde hat ein Schloss bereits gekauft.","Leer: Alle Familien wollen dieselbe Pumpe.","Block: Der Bedarf besteht nur aus einer Frage zum Preis."],"why":"Beide Stimmen belegen einen Wunsch nach Informationen zur Passung. Aus ihnen folgt weder ein Verkauf noch eine Garantie für alle Fahrräder.","hint":"Was wurde gefragt? Was wurde daraus lediglich gefolgert?","steps":"Schreibe den Kern der Aussage in einem Satz auf. Füge keine Eigenschaft hinzu, die im Fall fehlt.","example":"‚Welches Modell passt?‘ ist eine Bitte um Orientierung und keine Bestätigung der Passung.","sourceRefs":["M1","M2"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Beratung sinnvoll einplanen","scene":"Für Block wird ein Tisch vorgeschlagen, an dem die Fachkraft die Lichtbefestigung zeigt. Der Platz ist knapp; Hauptgang und Werkstattzugang müssen frei bleiben.","ask":"Welche Entscheidungen sind durch den Fall begründbar?","answer":[1,4],"options":["Der Tisch steht am besten quer im Hauptgang, damit alle die Vorführung sehen.","Die Fachkraft soll Lichtbefestigung bei Bedarf am Fahrrad zeigen können.","Der Beleg spricht dafür, nur Artikel zu einem festen Preis zu verkaufen.","Der Tisch ist zwingend, selbst wenn der freie Zugang mit ihm schwierig wird.","Vor dem Aufbau prüft ihr, ob auch mit abgestelltem Fahrrad Gang und Zugang frei bleiben.","Die Lichtberatung wird ausschließlich an die Information in Leer verwiesen."],"why":"Die Kundenstimme stützt die Demonstration. Die konkrete Lösung muss das Fahrrad einplanen und die Verkehrswege freihalten. Der Tisch selbst ist damit keine Pflicht.","hint":"Unterscheide das Ziel der Beratung vom vorgeschlagenen Möbel.","steps":"Lies die Kundenstimme und prüfe anschließend, welche Platzvorgabe auch beim Einsatz eingehalten werden muss.","example":"Eine kurze Vorführung kann je nach Fläche auch ohne zusätzlichen Tisch gelingen.","sourceRefs":["M1","M3"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Selbstbedienung ermöglichen","scene":"In Leer möchte eine Familie eine Pumpe für ihre Ventile finden. Samstags ist niemand fest für die Beratung auf der Aktionsfläche eingeteilt.","ask":"Welche Maßnahmen greifen beide Fallinformationen auf?","answer":[0,3,5],"options":["Die Ventilarten werden auf dem Regalschild verständlich genannt.","Ihr verspricht, dass jedes Produkt ohne Prüfung zu allen Fahrrädern passt.","Ihr schreibt nur ‚Aktion‘ aufs Schild und legt alle Pumpen ohne erkennbare Ordnung zusammen.","Die verfügbaren Pumpen werden nach gut sichtbaren Merkmalen vergleichbar angeordnet.","Ihr plant stattdessen voraus, dass die Fachkraft jede Familie bis zum Regal begleitet.","Falls jemand unsicher bleibt, weist ihr auf die Information hin."],"why":"Die Beschriftung und geordnete Auswahl helfen beim Selberfinden. Ein Hinweis auf die Information deckt offene Fragen ab, ohne dauerhaft besetzte Beratung vorauszusetzen.","hint":"Was muss man selbst erkennen können, bevor man nachfragen muss?","steps":"Prüfe den Anfang der Suche, den Produktvergleich und den Weg bei einer offenen Frage.","example":"Ein Merkmal wie die passende Ventilart hilft mehr als ein Schild, auf dem nur ‚Angebot‘ steht.","sourceRefs":["M2","M4"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Sortiment oder Präsentation","scene":"In der Vergleichsmatrix müsst ihr erkennen lassen, ob es um die Warenauswahl oder um den Aufbau geht.","ask":"Welche Aussagen sind Anforderungen an die Präsentation?","answer":[0,2,4],"options":["Ordnet Pannenzubehör in einem gut auffindbaren Bereich an.","Wählt Zubehör zum sicheren Abstellen für Block aus.","Beschriftet die Ventilarten am Regal deutlich.","Nehmt passende Lichter für Fahrten bei Dunkelheit ins Angebot auf.","Richtet einen Vorführbereich ein, ohne den Werkstattzugang zu versperren.","Wählt für Leer Zubehör für Familienausflüge aus."],"why":"Anordnung, Beschriftung und Vorführbereich betreffen, wie die Ware gezeigt wird. Die anderen Vorschläge legen fest, welche Ware angeboten wird.","hint":"Achte auf die Frage: Was wird verkauft oder wie wird es gezeigt?","steps":"Ordne jeden Vorschlag einer der beiden Fragen zu und prüfe, ob er zugleich einen Ladenbezug enthält.","example":"Ein Pumpenmodell auszuwählen betrifft das Sortiment. Es nach Ventilart zu beschriften betrifft die Präsentation.","sourceRefs":["M5"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Flächenplan kontrollieren","scene":"Die Aktionsfläche für Leer misst 6,40 m × 3,50 m. Eine Gondel misst 1,60 m × 0,60 m. Ihr zeichnet im Maßstab 1:25.","ask":"Welche Maße gehören in euren Plan?","answer":[1,3],"options":["Die Aktionsfläche ist 22,4 cm × 14,0 cm groß.","Die Aktionsfläche ist 25,6 cm × 14,0 cm groß.","Eine Gondel ist 4,0 cm × 1,6 cm groß.","Eine Gondel ist 6,4 cm × 2,4 cm groß.","Eine Gondel ist 16,0 cm × 6,0 cm groß.","Der Maßstab wird nur auf die Aktionsfläche angewendet; die Gondeln bleiben in Originalgröße."],"why":"640 ÷ 25 = 25,6 und 350 ÷ 25 = 14. Bei der Gondel führen 160 ÷ 25 und 60 ÷ 25 zu 6,4 cm × 2,4 cm.","hint":"Verwende für jeden einzelnen Längenwert dieselbe Rechnung.","steps":"Wandle Meter in Zentimeter um. Teile anschließend alle vier Zahlen durch 25.","example":"1,00 m werden bei 1:25 zu 4,0 cm. Länge und Tiefe werden einzeln umgerechnet.","sourceRefs":["M3"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Flächen fair vergleichen","scene":"Block hat 3,60 m × 3,20 m. Die Bike Arena hat 6,40 m × 3,50 m. Der feste Beratungstresen steht innerhalb der Fläche bei Block. Die angrenzenden Hauptgänge bleiben frei.","ask":"Welche Schlussfolgerungen sind richtig?","answer":[0,1,5],"options":["Die rechteckige Aktionsfläche bei Block misst rechnerisch 11,52 m².","Die rechteckige Aktionsfläche in Leer misst rechnerisch 22,40 m².","Der Hauptgang darf in beiden Läden zur Aktionsfläche hinzugerechnet und belegt werden.","Da 6,40 m weniger als doppelt so lang wie 3,60 m sind, haben beide Läden gleich viel Platz.","Die gesamten 11,52 m² bei Block stehen für bewegliche Aktionsmöbel frei.","Die Rechteckfläche allein reicht nicht, um den Aufbau mit dem Tresen und allen Wegen zu beurteilen."],"why":"Die beiden Rechtecke sind unterschiedlich groß. Der Tresen bindet bei Block einen Teil des Platzes. Außerdem dürfen angrenzende Gänge nicht verstellt werden.","hint":"Vergleiche Fläche und tatsächlich nutzbaren Platz.","steps":"Berechne pro Laden Länge × Breite. Prüfe anschließend die festen Hindernisse und Zugänge.","example":"Eine Fläche von 4 m × 3 m hat 12 m². Ein festes Möbel verändert die nutzbare Anordnung, obwohl das Rechteck gleich groß bleibt.","sourceRefs":["M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Zahlen nicht überdeuten","scene":"In einem Entwurf steht: ‚Bei Block ist Licht das häufigste Hauptanliegen. Deshalb will fast die ganze Kundschaft Licht kaufen.‘","ask":"Wie machst du die Aussage belastbar?","answer":[1,3],"options":["Schreibe ‚neun Verkäufe‘ statt ‚fast die ganze Kundschaft‘.","Nenne neun von 20 erfassten Anfragen zur Sichtbarkeit auf dem Arbeitsweg.","Weite den Befund auf alle Kundinnen und Kunden im Jahresverlauf aus.","Nutze den Befund als Hinweis für die Warenauswahl in dieser Aktion.","Behaupte, dass die restlichen elf Anfragen bei Leer erfasst wurden.","Streiche alle Nachfragedaten, weil sie die Zukunft nicht sicher vorhersagen."],"why":"Die 20 Anfragen sind eine begrenzte Beobachtung. Neun sprechen für Sichtbarkeit als wichtigen Bedarf, belegen aber keine Kaufentscheidung der gesamten Kundschaft.","hint":"Welche Gruppe und welcher Zeitraum stehen tatsächlich im Fall?","steps":"Ersetze große Behauptungen durch die Zahl, den Standort und das gezählte Anliegen.","example":"Ein hoher Anteil in einer erfassten Stichprobe ist ein Auswahlhinweis. Eine sichere Prognose ist es nicht.","sourceRefs":["M1"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Priorität korrigieren","scene":"Dein erster Entwurf nennt ein zusätzliches Schild bei Leer zwingend und freie Gondelseiten wünschenswert. M3 sieht Ware auf beiden Seiten vor; die Vorder- und Rückseite sollen erreichbar bleiben.","ask":"Was verbesserst du?","answer":[2,3,5],"options":["Ich halte an der Einordnung fest, weil mein Entwurf schon fertig ist.","Ich streiche beide Punkte und plane eine größere Verkaufsfläche.","Ich halte den Zugang zu beiden Warenseiten als notwendige Aufbauvorgabe fest.","Ich prüfe, ob eine gute Regalbeschriftung das zusätzliche Schild ersetzen kann.","Ich erkläre das Schild in jedem Fall zur Pflicht, weil Leer mehr Platz hat.","Ich vermerke, welche Fallangabe meine ursprüngliche Reihenfolge geändert hat."],"why":"Die beidseitige Erreichbarkeit trägt hier die Selbstbedienung. Ein separates Schild ist nur eine von mehreren Möglichkeiten, die Ware zu kennzeichnen.","hint":"Frage bei jedem Punkt: Was wäre verloren, wenn wir ihn weglassen?","steps":"Vergleiche den Zweck der Vorgabe mit möglichen gleichwertigen Alternativen.","example":"Ein Regalzugang hängt vom Aufbau ab. Die Beschriftung kann am Regal oder auf einem nahen Schild stehen.","sourceRefs":["M3","M4","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Eine Rückmeldung schreiben","scene":"Eine andere Gruppe notiert bei Leer: ‚Pumpen neben den Hauptgang stellen. Das ist gut.‘ Ihr gebt Feedback zur Vergleichsmatrix.","ask":"Welche Rückmeldungen helfen bei der Überarbeitung?","answer":[0,2,4],"options":["Ergänzt die Kundenfrage zur Ventilpassung als Beleg für eine klare Beschriftung.","Die Idee ist schlecht, weil uns Pumpen nicht interessieren.","Erklärt, wie der Hauptgang bei diesem Standort frei bleibt.","Schreibt einfach, dass die gesamte Idee zwingend ist.","Unterscheidet bei Bedarf die Warenauswahl von der Platzierung.","Nehmt den Vorschlag unverändert, weil darin schon der Standort vorkommt."],"why":"Die Rückmeldungen fordern Belege und prüfen eine konkrete Vorgabe. Sie zeigen außerdem, wo sich Entscheidungen über Ware und Aufbau vermischen.","hint":"Was fehlt im Satz, damit Jan handeln kann?","steps":"Nenne eine beobachtbare Verbesserung und knüpfe sie an einen Beleg oder ein Feld der Matrix.","example":"Statt ‚schöner machen‘ hilft ‚Beschrifte die Ventilarten so, dass sie am Regal lesbar sind‘.","sourceRefs":["M2","M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Im Pitch begründen","scene":"Eine Teamkollegin möchte im kurzen Pitch nur aufzählen, welche Waren beide Läden zeigen. Jan fragte nach dem wichtigsten Unterschied und seiner Folge.","ask":"Welche Ergänzungen sollen in den Pitch?","answer":[1,3],"options":["Ein langer Bericht darüber, wie die Gruppe abgestimmt hat.","Ein Beispiel dafür, wie persönliche Beratung bei Block den Aufbau verändert.","Nur die Zahl der Beteiligten aus beiden Läden.","Ein Beispiel dafür, wie Kundinnen und Kunden in Leer beim Selbstfinden unterstützt werden.","Die pauschale Aussage, dass Leer in allen Bereichen besser ist.","Ein unbelegtes Versprechen, dass der Aufbau Verkaufszahlen garantiert steigert."],"why":"Zwei Beispiele zu derselben Verkaufsfrage zeigen, warum sich die Aufbauten unterscheiden. Die Beispiele müssen am Fall überprüfbar sein.","hint":"Nenne die praktische Folge eines Unterschieds für jeden Laden.","steps":"Wähle je eine kurze Beobachtung. Verbinde sie mit einer konkreten Anforderung.","example":"‚Werkstattzugang und Platz am Beratungsort‘ ist für Jan greifbarer als ‚Block braucht einen anderen Aufbau‘.","sourceRefs":["Handlungssituation","M1","M2","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Beleg und Anforderung verbinden","scene":"In der digitalen Matrix steht in einer Zelle nur ‚M3‘. Der Vorschlag lautet: ‚Den Durchgang bei Block frei halten.‘","ask":"Welche Ergänzungen machen den Eintrag prüfbar?","answer":[0,3,5],"options":["Notiere, dass der 1,20 m breite Hauptdurchgang zum Werkstattzugang führt.","Verlinke die Quelle, ohne die relevante Information im Ergebnis zu nennen.","Belege die Gangbreite mit einer ungeprüften Erinnerung aus einem anderen Laden.","Ordne die betroffene Zeile Block zu und gib M3 als Quelle an.","Ersetze das Maß durch die Angabe ‚gefühlt breit genug‘.","Kennzeichne, dass der Zugang laut Flächenvorgabe frei bleiben muss."],"why":"Eine konkrete Angabe zeigt, welche Stelle in M3 den Vorschlag trägt. Standort, Quelle, Maß und Verpflichtung müssen zusammen erkennbar bleiben.","hint":"Eine Quellen-ID allein verrät noch nicht, welche Angabe gemeint ist.","steps":"Trage Nummer der Quelle und die belegende Einzelangabe in die passende Zeile ein.","example":"‚M3, Hauptdurchgang 1,20 m‘ ist genauer als ‚M3, Platz‘.","sourceRefs":["M3","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Skizze und Sprachnachricht abgleichen","scene":"Eine Sprachnachricht nennt für Leer einen Hauptgang an der langen Seite. Eure Skizze zeigt den Gang an der kurzen Seite. M3 enthält die Skizzenhilfe.","ask":"Welche Überarbeitung ist fachlich sauber?","answer":[2,3,5],"options":["Passt die Nachricht an eure Skizze an und gebt sie als Original wieder.","Lasst den Gang an der kurzen Seite, wenn das auf dem Blatt besser aussieht.","Vergleicht den Sprechtext mit der Skizzenhilfe und korrigiert die Lage in eurer Zeichnung.","Tragt den Gang an der 6,40 m langen Seite ein.","Verzichtet auf den Lagehinweis, weil das Flächenmaß ohnehin stimmt.","Prüft, ob geänderte Regalpositionen den Zugang und die Gondelseiten frei lassen."],"why":"Sprechtext und M3 zeigen dieselbe Lage. Die Zeichnung wird daran angepasst und die Position der betroffenen Möbel danach erneut geprüft.","hint":"Der Fehler betrifft die Lage und kann Folgen für den Aufbau haben.","steps":"Sucht zuerst die lange Seite. Prüft dann, was sich für Zugang und Erreichbarkeit der Regale ändert.","example":"Eine Skizze kann die richtigen Gesamtmaße enthalten und trotzdem den Gang an der falschen Stelle zeigen.","sourceRefs":["M3","M4"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Eine Empfehlung für beide Standorte","scene":"Jan fragt, ob für beide Geschäfte genau derselbe Aufbau freigegeben werden soll. Er will die Vorbereitung einfach halten und gleichzeitig, dass die Aktion in beiden Läden funktioniert.","ask":"Welche Aussagen könnt ihr fachlich gut vertreten?","answer":[1,4],"options":["Die größere Aktionsfläche in Leer macht Beratung bei Block überflüssig.","Ein gemeinsames Aktionsmotiv ist denkbar; der Aufbau muss an Verkaufsform und Platz je Laden angepasst werden.","Da in beiden Läden 20 Anfragen erfasst wurden, haben sie dieselbe Zielgruppe.","Für Block reicht die Planung anhand des Beratungstresens. Kundenanfragen spielen für die Auswahl keine Rolle.","Zwingende Vorgaben wie freie Wege prüft ihr für jeden Standort vor der Freigabe.","Einen gemeinsamen Aufbau kann man freigeben, sobald er im größeren Laden passt."],"why":"Ein gemeinsamer Rahmen lässt sich mit standortgerechten Flächen verbinden. Gleiche Fallzahlen bedeuten keine identischen Bedürfnisse. Beide Aufbauten müssen ihre Vorgaben erfüllen.","hint":"Sucht zuerst Gemeinsamkeiten. Prüft danach jede Bedingung, die je Laden anders ist.","steps":"Vergleicht pro Standort Nachfrage, Verkaufsform und Fläche. Formuliert, was gleich aussehen kann und was geprüft werden muss.","example":"Zwei Läden können dasselbe Aktionsthema nutzen und unterschiedliche Warenträger einsetzen.","sourceRefs":["Handlungssituation","M1","M2","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Den Vergleich beginnen","scene":"Übungsvariante: Für das Treffen um 10 Uhr bleibt wenig Zeit. Sarah würde gern denselben Aufbau vorbereiten. Jan bittet dich um eine kurze, belastbare Empfehlung für Aurich und Leer.","ask":"Womit beginnst du?","options":["Ich markiere je Laden eine Kundenaussage und die passenden Angaben zur Verkaufsform.","Ich sammle je Laden eine Rückfrage, die sich mit dem Verkaufsteam klären lässt.","Ich markiere im Plan die Bereiche, die zwingend frei bleiben müssen.","Ich vergleiche beide Kurzprofile in drei Spalten: Nachfrage, Verkaufsform und Fläche.","Ich frage die Ladenvertretungen, wie Kundinnen und Kunden vor Ort am besten durch die Aktion finden.","Ich notiere je Laden die feste Ausstattung und den nutzbaren Zugang als erste Planungsgrenzen."],"consequences":["Zwei beobachtete Kaufanlässe werden zum Ausgangspunkt deines Vergleichs.","Du gehst mit einer klaren Frage an beide Läden in die Vorbereitung.","Die freien Wege stehen fest, bevor du Möbel einplanst.","Die Belege lassen sich nach denselben Kriterien prüfen.","Du startest mit der Erfahrung der Menschen, die den Aufbau nutzen.","Die begrenzenden Maße und Warenträger sind markiert."],"sourceRefs":["Handlungssituation","M1","M2","M3"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":24,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"c":3,"title":"Zwei Vorschläge eingrenzen","scene":"Übungsvariante: Sarah skizziert einen gemeinsamen Vorführtisch. Als Alternative schlägt Sebastian für Block einen Beratungsplatz und für Leer eine gut beschriftete Selbstbedienungsfläche vor.","ask":"Wie vergleichst du beide Vorschläge?","options":["Ich halte pro Vorschlag fest, welche Kundenstimme und welche Verkaufsform dafür sprechen.","Ich bitte beide Läden um Rückmeldung dazu, wie die Kundschaft bei jedem Vorschlag Hilfe bekommt.","Ich prüfe beide Vorschläge zuerst an den Gang- und Zugangsmaßen.","Ich vergleiche anhand von M1 und M2, welche Anfrage jede Variante abdeckt und wo Belege fehlen.","Ich kläre mit der Fachkraft bei Block und der Information in Leer, was sie beim Aufbau leisten können.","Ich zeichne beide Varianten grob ein und markiere Engstellen um Tresen, Gondeln und Wege."],"consequences":["Du kannst zeigen, welche Fallangabe für welchen Entwurf spricht.","Mögliche Lücken aus Sicht der Ladenvertretungen werden sichtbar.","Unpassende Möbelpositionen fallen schon vor der weiteren Planung auf.","Deine Vergleichszeilen trennen belegte Bedürfnisse von offenen Punkten.","Die Aufgaben der Beschäftigten sind vorläufig geklärt.","Die beiden Skizzen zeigen klar, wo der Platz knapp wird."],"sourceRefs":["M1","M2","M3"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":25,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":0,"title":"Eine neue Bedingung prüfen","scene":"Übungsvariante: Block meldet kurz vor dem Termin, dass für einen Teil des Vormittags zusätzliche Räder zur Werkstatt geschoben werden. Der Hauptgang bleibt frei. Der Entwurf muss auf diese Nutzung reagieren.","ask":"Wie arbeitest du die Nachricht ein?","options":["Ich ergänze die Nachricht als neuen Beleg und prüfe, welche Zeile zum Aufbau angepasst werden muss.","Ich frage das Block-Team, an welcher Stelle beim Schieben der Räder die geplante Beratung stören könnte.","Ich prüfe die freie Wegbreite im Plan und halte den zusätzlichen Verkehr als Aufbaugrenze fest.","Ich ergänze die Werkstattmeldung in der Vergleichsmatrix neben der ursprünglichen Flächenvorgabe.","Ich bespreche mit Beratung und Werkstatt, wie die Vorführung daneben ohne Behinderung stattfinden kann.","Ich prüfe zwei Tischpositionen und verwerfe jede, bei der Fahrrad oder Beratung in den Durchgang geraten."],"consequences":["Jede Änderung bleibt auf die neue Information zurückführbar.","Die Antwort aus dem Laden kann eine konkrete Engstelle zeigen.","Du schützt den verpflichtenden Durchgang auch bei mehr Betrieb.","Alter und neuer Nachweis sind klar voneinander zu unterscheiden.","Die betroffenen Beschäftigten bringen ihre Arbeitsabläufe in den Entwurf ein.","Du behältst nur Positionen, die sich auch im Betrieb einrichten lassen."],"sourceRefs":["M1","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":26,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":2,"title":"Leer mitdenken","scene":"Übungsvariante: Die Ladenvertretung aus Leer will, dass die Kundschaft Ventiltypen leicht erkennt. Samstags bleibt die Aktionsfläche wie im Ausgangsfall ohne feste Beratung.","ask":"Wie legst du den nächsten Schritt für Leer fest?","options":["Ich leite aus der Frage der Familie eine prüfbare Anforderung an die Regalbeschriftung ab.","Ich bitte die Information um eine Rückmeldung, an welcher Angabe Kundinnen und Kunden oft scheitern.","Ich plane Regalhinweise so ein, dass Warenseiten und Hauptgang frei bleiben.","Ich verknüpfe in der Matrix die Kundenstimme mit der fehlenden festen Beratung als Begründung.","Ich lasse eine Person aus dem Team die Pumpenwahl aus Kundensicht ausprobieren.","Ich prüfe, ob ein freistehender Schildhalter in den Plan passt und andernfalls eine Regalbeschriftung genügt."],"consequences":["Die Beschriftung lässt sich an einer konkreten Kaufanfrage prüfen.","Der Vorschlag berücksichtigt die Erfahrung der Anlaufstelle.","Die Information bleibt auffindbar und die Wege bleiben nutzbar.","Jan kann die Entscheidung aus zwei Fallangaben nachvollziehen.","Das Team bekommt direkte Rückmeldung zum Selberfinden.","Du hast zwei realistische Kennzeichnungsvarianten für den verfügbaren Platz."],"sourceRefs":["M2","M3","M4","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":27,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":4,"title":"Die Matrix prüfen","scene":"Übungsvariante: Beide Vorschläge sind ausgearbeitet. Jan sieht die Matrix gleich zum ersten Mal. In ihr müssen Anforderung, Beleg und Priorität schnell auffindbar sein.","ask":"Welche Abschlussprüfung schließt an deinen Weg an?","options":["Ich kontrolliere für jede Anforderung, ob die angegebene Quelle genau diese Aussage stützt.","Ich lasse das Team je eine Rückfrage zu Aurich und Leer aus Sicht der Ladenvertretung formulieren.","Ich prüfe jede Muss-Vorgabe und markiere, wo im jeweiligen Plan sie überprüfbar ist.","Ich ergänze die konkrete Zahl, das Maß oder die wörtliche Kundenfrage, wenn bisher nur eine Quelle genannt ist.","Ich hole eine gezielte Rückmeldung dazu ein, ob beim Lesen wichtige Gründe unklar bleiben.","Ich trenne die zwingenden Punkte von optionalen Verbesserungen und prüfe die umsetzbare Mindestfassung."],"consequences":["Die Belegkette ist pro Zeile nachvollziehbar.","Du erkennst, wo Jan oder die Läden eine verständlichere Begründung brauchen.","Zwingende Vorgaben sind im Ergebnis klar mit dem Aufbau verbunden.","Die Quellenhinweise führen zu überprüfbaren Einzelangaben.","Das Team kann eine unklare Stelle vor dem Treffen präzisieren.","Die Empfehlung bleibt auch bei wenig Platz oder Zeit realistisch."],"sourceRefs":["M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":28,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":1,"title":"Die Entscheidung empfehlen","scene":"Übungsvariante: Jan fragt im Treffen, warum sich die Aufbauten unterscheiden sollen, obwohl ein gemeinsames Motiv Zeit spart. Für eure Antwort habt ihr etwa eine Minute.","ask":"Wie fasst du deine Empfehlung zusammen?","options":["Ich nenne je Laden einen Beleg zur Verkaufsform und die praktische Folge für den Aufbau.","Ich fasse die Anforderungen beider Ladenvertretungen zusammen und benenne die gemeinsame Lösungsidee.","Ich erkläre zuerst die beiden Aufbaugrenzen und dann, welche Gestaltung je Laden darin möglich ist.","Ich zeige eine belegte Vergleichszeile je Standort und leite daraus die Empfehlung ab.","Ich verknüpfe je eine Rückmeldung aus Beratung und Selbstbedienung mit unserer Empfehlung.","Ich nenne die zwingenden Vorgaben und erläutere, welche Teile des gemeinsamen Motivs trotzdem umgesetzt werden können."],"consequences":["Jan bekommt zwei nachvollziehbare Belege und eine begründete Empfehlung.","Die Empfehlung zeigt, warum beide Ladenteams mit der Entscheidung arbeiten können.","Die Empfehlung ist mit den örtlichen Grenzen verbunden.","Jan kann die Argumente in der schriftlichen Matrix direkt wiederfinden.","Die unterschiedlichen Arbeitsweisen bleiben in der Entscheidung sichtbar.","Jan weiß, was für die Umsetzung unverzichtbar ist und wo Spielraum bleibt."],"sourceRefs":["Handlungssituation","M1","M2","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":29,"l":3,"type":"story","caseLabel":"LS 6.1 · Die Nachfrage an zwei Standorten vergleichen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
